-- Arbeitsrecht Berufsbildung > Pflichten von Arbeitgebern > Ausbildung gewissenhaft durchführen (§ 14 Abs. 1 BBiG)
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einen Fachinformatiker gewissenhaft ausbilden?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG verpflichtet den Betrieb dazu"}, {"text": "Nein", "correct": false, "because": "Gewissenhafte Ausbildung ist Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein Betrieb einen Fachinformatiker nur mit Botengängen beschäftigen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 14 Abs. 1 BBiG verlangt eine fachgerechte Ausbildung"}, {"text": "Ja", "correct": false, "because": "Botengänge sind nicht gewissenhaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einem Fachinformatiker die nötigen Arbeitsmittel bereitstellen?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG fordert die Bereitstellung"}, {"text": "Nein", "correct": false, "because": "Arbeitsmittel sind Teil der Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Darf ein Betrieb die Ausbildung eines Fachinformatikers vernachlässigen?', 2, '[{"text": "Nein", "correct": true, "because": "§ 14 Abs. 1 BBiG schreibt gewissenhafte Durchführung vor"}, {"text": "Ja", "correct": false, "because": "Vernachlässigung ist unzulässig"}]'),
('00000000-0000-0000-0000-000000000000', 'Muss ein Ausbildungsbetrieb einem Fachinformatiker regelmäßige Unterweisung bieten?', 2, '[{"text": "Ja", "correct": true, "because": "§ 14 Abs. 1 BBiG verlangt Unterweisung"}, {"text": "Nein", "correct": false, "because": "Unterweisung ist Pflicht"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche gesetzliche Grundlage verpflichtet einen Betrieb, einen Fachinformatiker gewissenhaft auszubilden?', 2, '[{"text": "§ 14 Abs. 1 BBiG", "correct": true, "because": "Regelt die Pflicht zur gewissenhaften Ausbildung"}, {"text": "§ 13 BBiG", "correct": false, "because": "Bezieht sich auf Pflichten des Auszubildenden"}, {"text": "§ 22 BBiG", "correct": false, "because": "Regelt die Kündigung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was bedeutet es, wenn ein Betrieb einen Fachinformatiker gewissenhaft ausbildet?', 3, '[{"text": "Er vermittelt die vorgeschriebenen Fertigkeiten", "correct": true, "because": "§ 14 Abs. 1 BBiG fordert dies"}, {"text": "Er lässt ihn nur einfache Aufgaben machen", "correct": false, "because": "Nicht gewissenhaft"}, {"text": "Er überlässt die Ausbildung der Berufsschule", "correct": false, "because": "Betrieb ist verantwortlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgabe gehört zur gewissenhaften Ausbildung eines Fachinformatikers?', 3, '[{"text": "Schulung in Programmierung", "correct": true, "because": "Entspricht § 14 Abs. 1 BBiG"}, {"text": "Nur administrative Tätigkeiten", "correct": false, "because": "Nicht fachgerecht"}, {"text": "Keine Unterweisung bieten", "correct": false, "because": "Widerspricht der Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Wer ist verpflichtet, die Ausbildung eines Fachinformatikers gewissenhaft durchzuführen?', 2, '[{"text": "Der Ausbildungsbetrieb", "correct": true, "because": "§ 14 Abs. 1 BBiG legt dies fest"}, {"text": "Die IHK", "correct": false, "because": "IHK überwacht nur"}, {"text": "Die Berufsschule", "correct": false, "because": "Schule ergänzt die Ausbildung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Betrieb einen Fachinformatiker nicht gewissenhaft ausbildet?', 3, '[{"text": "Die IHK kann einschreiten", "correct": true, "because": "IHK überwacht die Einhaltung von § 14 Abs. 1 BBiG"}, {"text": "Der Auszubildende übernimmt die Ausbildung", "correct": false, "because": "Nicht seine Aufgabe"}, {"text": "Nichts passiert", "correct": false, "because": "Verstoß hat Konsequenzen"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was muss ein Ausbildungsbetrieb tun, um einen Fachinformatiker gewissenhaft auszubilden?', 4, '[{"text": "Fachgerechte Unterweisung bieten", "correct": true, "because": "§ 14 Abs. 1 BBiG fordert dies"}, {"text": "Arbeitsmittel bereitstellen", "correct": true, "because": "Notwendig für die Ausbildung"}, {"text": "Nur einfache Aufgaben zuteilen", "correct": false, "because": "Nicht gewissenhaft"}, {"text": "Den Ausbildungsrahmenplan einhalten", "correct": true, "because": "Vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenzen drohen einem Betrieb, der einen Fachinformatiker nicht gewissenhaft ausbildet?', 3, '[{"text": "Verwarnung durch die IHK", "correct": true, "because": "IHK kann eingreifen"}, {"text": "Schadensersatzforderungen des Auszubildenden", "correct": true, "because": "Bei Nachweis möglich"}, {"text": "Automatische Schließung", "correct": false, "because": "Nicht vorgesehen"}, {"text": "Verlust der Ausbildungsberechtigung", "correct": true, "because": "Bei schweren Verstößen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Inhalte muss ein Betrieb einem Fachinformatiker gewissenhaft vermitteln?', 4, '[{"text": "Programmierkenntnisse", "correct": true, "because": "Teil der IT-Ausbildung"}, {"text": "Netzwerkadministration", "correct": true, "because": "Relevanter Inhalt"}, {"text": "Nur Büroarbeiten", "correct": false, "because": "Nicht fachgerecht"}, {"text": "Berufsschulstoff ergänzen", "correct": true, "because": "Gewissenhaftigkeit umfasst dies"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört nicht zur gewissenhaften Ausbildung eines Fachinformatikers?', 3, '[{"text": "Unterweisung in aktuellen Technologien", "correct": false, "because": "Teil der Pflicht"}, {"text": "Bereitstellung eines Computers", "correct": false, "because": "Notwendig"}, {"text": "Auszubildenden allein lassen", "correct": true, "because": "Widerspricht § 14 Abs. 1 BBiG"}, {"text": "Förderung der Prüfungsvorbereitung", "correct": false, "because": "Gewissenhaft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen zeigen, dass ein Betrieb einen Fachinformatiker gewissenhaft ausbildet?', 3, '[{"text": "Regelmäßige Schulungen anbieten", "correct": true, "because": "Fördert Fertigkeiten"}, {"text": "Arbeitsmittel zur Verfügung stellen", "correct": true, "because": "§ 14 Abs. 1 BBiG verlangt dies"}, {"text": "Nur einfache Aufgaben zuteilen", "correct": false, "because": "Nicht ausreichend"}, {"text": "Feedback zur Leistung geben", "correct": true, "because": "Unterstützt Entwicklung"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Ein Betrieb muss einen Fachinformatiker gewissenhaft ausbilden. b) Arbeitsmittel sind nicht erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Gewissenhafte Ausbildung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Gewissenhafte Ausbildung umfasst Unterweisung. b) Der Betrieb darf die Ausbildung vernachlässigen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Unterweisung Pflicht, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein Betrieb muss den Ausbildungsrahmenplan einhalten. b) Gewissenhafte Ausbildung gilt nur in der Probezeit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rahmenplan bindend, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Ein Betrieb muss einen Fachinformatiker auf die IHK-Prüfung vorbereiten. b) Gewissenhafte Ausbildung bedeutet nur Arbeitsmittel stellen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prüfungsvorbereitung Pflicht, b) ist unvollständig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Gewissenhafte Ausbildung schließt Netzwerkkenntnisse ein. b) Der Betrieb darf Botengänge als Hauptaufgabe zuteilen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Netzwerkkenntnisse relevant, b) ist falsch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

